import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  EventEmitter,
  Input,
  OnChanges,
  OnDestroy,
  OnInit,
  Output,
  SimpleChanges,
  ViewChild,
} from '@angular/core';
import { FilehaderComponent } from '../../../shared/components/myfiles/filehader/filehader.component';
import { PreviewComponent } from '../../../shared/components/myfiles/preview/preview.component';
import { TableComponent } from '../../../shared/components/myfiles/table/table.component';
import { CommonfunctionService } from '../../../core/utility/commonfunction.service';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatSelectChange, MatSelectModule } from '@angular/material/select';
import { MatInputModule } from '@angular/material/input';
import { FormsModule } from '@angular/forms';
import moment from 'moment';
import { DatepickerComponent } from '../../../shared/components/datepicker/datepicker.component';
import { ButtonComponent } from '../../../shared/components/button/button.component';
import { SearchComponent } from '../../../shared/components/search/search.component';
import { HeaderService } from '../../../core/services/header/header.service';
import { CommonModule } from '@angular/common';
import { PresentsetupService } from '../../services/presentsetup/presentsetup.service';

import {
  downloadReport,
  RecentFiles,
  presentDocType,
  presentGetFiles,
  presentSetupData,
  RecentFilesIDS,
  TypeRes,
} from '../../interfaces/presentsetup';
import {
  CdkVirtualScrollViewport,
  ScrollingModule,
} from '@angular/cdk/scrolling';
import { RecentfileComponent } from '../../../shared/components/recentfile/recentfile.component';
import { IconComponent } from '../../../shared/components/icon/icon.component';
import { Subscription } from 'rxjs';
import { CommunicationService } from '../../../shared/services/communication/communication.service';
import { FilecolumnService } from '../../../shared/services/filecolumn/filecolumn.service';
import { MatDialog, MatDialogRef } from '@angular/material/dialog';
import { ActionbarComponent } from '../../../shared/components/actionbar/actionbar.component';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { TOOL_EVENT_TYPES, toolEvents } from '../../../pdf/interfaces/pdf.interface';
import { TostbarService } from '../../../core/services/tost/tostbar.service';
import { ErrorHandlerUtil } from '../../../userpanel/utility/error-handler.util';
import { TranslateModule } from '@ngx-translate/core';
import {
  ACTIONBAR_ACTION_TYPES,
  ACTIONBAR_BUTTONS,
  ActionbarButtonConfig,
} from '../../../shared/interfaces/actionbar.interface';

@Component({
  selector: 'app-present-history',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [
    FilehaderComponent,
    PreviewComponent,
    TableComponent,
    MatFormFieldModule,
    MatSelectModule,
    MatInputModule,
    FormsModule,
    DatepickerComponent,
    ButtonComponent,
    SearchComponent,
    CommonModule,
    TranslateModule,
    ScrollingModule,
    RecentfileComponent,
    IconComponent, MatCheckboxModule
  ],
  templateUrl: './present-history.component.html',
  styleUrl: './present-history.component.scss',
})
export class PresentHistoryComponent implements OnInit, OnChanges, OnDestroy {
  private async init(): Promise<void> {
    this.hs.nCaseid = this.nCaseid;
    this.presentSession = await this.PSservice.getRvalue(this.nCaseid);

    this.subTypes = await this.PSservice.getSTypes(this.nCaseid);

    this.cdr.detectChanges();

    await this.getrecentfile(1);
    await this.getPresentation();
  }
  @Input() nCaseid: string;
  reqcols: any = {};
  recentFiles: presentGetFiles[] = [];
  selected: string = '';
  viewlist: any[] = [];

  presentSession: presentSetupData;
  limit = 30;
  isPreview: boolean = false;

  nSubtypeid: number = 0;
  dStartDt = '';
  dEndDt = '';

  subTypes: TypeRes[] = [];

  isStar: boolean = false;

  // present file history
  @Input() bShowPresentHistory: boolean = false;
  @Output() presentHistory = new EventEmitter<toolEvents>();
  @Input() nTypeid: number;
  @Output() OnFileSelected: EventEmitter<any> = new EventEmitter<any>();
  @Output() handleSelection: EventEmitter<any> = new EventEmitter<any>();

  @Input() selectedBundleDetails: string[] = [];
  @Input() presentDocType: presentDocType;
  @Input() coreFiles: string[];

  @Input() isChooser: boolean = false;

  @Input() recentFileIds: string[] = [];
  @Output() recentFileIdsChange: EventEmitter<any> = new EventEmitter<any>();

  recentChooseDocs: { id: number; bid: number }[] = []; // recent files from choose-docs in presentation

  @Input() disabledFiles: string[];
  removedDocs: string[] = [];

  cSearch: string = '';
  private evsubscription: Subscription;

  @Input() enableFileDrag: boolean = false;
  nPresentid: string;
  presentlist: any[] = [];
  Lpageno: number = 1;
  cPname: string = ''; cSortby: string = 'cTab'; cLastOtype: string = 'cTab';
  public dialogRef: MatDialogRef<ActionbarComponent> | null = null;
  @ViewChild(CdkVirtualScrollViewport) viewport: CdkVirtualScrollViewport;


  isCheckAll: boolean = false;
  showCheckall: boolean = true; jFileids: string[] = []
  nSelectedFilesid: string[] = [];
  constructor(
    private readonly PSservice: PresentsetupService,
    private readonly cm: CommonfunctionService,
    private readonly cdr: ChangeDetectorRef,
    public readonly hs: HeaderService,
    private readonly cs: CommunicationService,
    private readonly fcs: FilecolumnService,
    private readonly dialog: MatDialog,
    private readonly tost: TostbarService,
  ) {
    this.reqcols = this.fcs.reqcols;
    this.reqcols['extra']['view'] = false;
    this.reqcols['remark']['view'] = true;

    hs.currentadminpath.next('my files');
  }

  ngOnInit(): void {
    this.checkEventSub();
    void this.init();
  }

  changeTable(event: any, x: any) {
    if (event == 'VIEW') {
      this.viewFile(x);
    }
  }

  handleSelectionEvent(): void {
    const files = this.nSelectedFilesid.map((id) => ({ nBundledetailid: id, cIscheck: true }));

    this.handleSelection.emit({ files, removedDocs: this.removedDocs });
    this.checkSelectALl();
    this.openactionbar();
    this.cdr.detectChanges();
  }

  viewFile(x) {
    if (this.isPreview) {
      this.updatePreviewMode(x);
    } else {
      this.isPreview = true;
      this.activateItem(x);
    }
    this.cdr.detectChanges();
  }

  activateItem(x) {
    if (
      this.viewlist.length === 0 ||
      this.viewlist[0].nBundledetailid !== x.nBundledetailid
    ) {
      x.active = true;
      this.cm.viewlist = [x];
      this.viewlist = this.cm.viewlist;
    }
  }

  updatePreviewMode(x) {
    const index = this.viewlist.findIndex(
      (e) => e.nBundledetailid === x.nBundledetailid
    );
    if (index > -1) {
      this.viewlist.splice(index, 1);
    } else {
      this.activateItem(x);
      this.viewlist.forEach((item, idx) => (item['active'] = idx === 0));
    }
    this.cm.viewlist = this.viewlist;
    this.cdr.detectChanges();
  }

  handleSelect(e: MatSelectChange, type: string) {
    if (type == 'T') {
      const value = Number.parseInt(e.value, 10);
      if (Number.isNaN(value)) {
        this.nSubtypeid = 0;
      } else {
        this.nSubtypeid = value;
      }

      this.getPresentation();
      this.cdr.detectChanges();
    }
    this.getrecentfile(1);
  }

  async getPresentation(): Promise<void> {
    const res = await this.PSservice.getPresentationList(this.nCaseid, this.presentSession?.nTypeid || this.nTypeid, this.nSubtypeid);
    this.presentlist = res
  }

  handleDate(e: string) {
    if (this.selected == e) {
      this.selected = '';
      this.dStartDt = '';
      this.dEndDt = '';
    } else {
      this.selected = e;
      let date = '';
      if (e == 'T') {
        date = moment(new Date()).format('YYYY-MM-DD');
      } else if (e == 'Y') {
        date = moment(new Date()).subtract(1, 'day').format('YYYY-MM-DD');
      }
      this.dStartDt = this.dEndDt = date;
    }
    this.cdr.detectChanges();
    this.getrecentfile(1);
  }

  dateFilter(e: string) {
    this.selected = '';
    this.dStartDt = e;
    this.dEndDt = e;
    this.cdr.detectChanges();
    this.getrecentfile(1);
  }

  gotoFile() {
    this.bShowPresentHistory = false;
    this.presentHistory.emit({ event: 'SHOW', data: { isshow: this.bShowPresentHistory } });
    this.cdr.detectChanges();
  }

  async getrecentfile(pageNumber: number) {
    try {
      type RecentFilesQuery = RecentFiles & {
        cSearch?: string;
        searchName?: string;
        cSortby?: string;
        cSorttype?: string;
        cPname?: string;
        dStartDt?: string;
        dEndDt?: string;
      };

      const mdl: RecentFilesQuery = {
        nCaseid: this.nCaseid,
        nTypeid: this.presentSession?.nTypeid || this.nTypeid,
        pageNumber,
        nLimit: this.limit,
        cSearch: this.cm.searchText,
        searchName: this.cm.searchName,
        cSortby: this.cSortby, cSorttype: this[this.cLastOtype] ? 'DESC' : 'ASC',
        cPname: this.cPname
      };

      this.cSearch = this.cm.searchText;

      if (this.nSubtypeid > 0) {
        mdl.nSubtypeid = this.nSubtypeid;
      }
      if (this.dStartDt && this.dEndDt) {
        mdl.dStartDt = this.dStartDt;
        mdl.dEndDt = this.dEndDt;
      }
      const res = await this.PSservice.recentFiles(mdl);
      if (pageNumber == 1) {
        this.jFileids = [];
      }
      if (this.isCheckAll) {
        res.forEach((e) => { e.cIscheck = true; });
      }
      this.recentFiles = pageNumber == 1 ? res : this.recentFiles.concat(res);


      if (this.selectedBundleDetails?.length > 0) {
        this.recentFiles.forEach((file) => {
          if (this.selectedBundleDetails.includes(file.nBundledetailid)) {
            file.cIscheck = true;
          }
        });
      }
      this.handleSelectionEvent();
    } catch (error) {
      this.tost.error(ErrorHandlerUtil.getErrorMessage(error));
    }
    this.cdr.detectChanges();
  }

  scrolled() {
    const end = this.viewport.getRenderedRange().end;
    const total = this.viewport.getDataLength();
    if (end === total) {
      const pageno = total / this.limit + 1;
      if (pageno % 1 || pageno < this.recentFiles.length / this.limit) {
        return;
      }
      if (this.Lpageno == pageno) { return };
      this.Lpageno = pageno;
      this.getrecentfile(pageno);
    }
  }

  recentOutput(event) {
    if (event.event == 'VIEW') {
      this.viewFile(event.data);
    }
  }

  starFiles() {
    this.isStar = !this.isStar;
    this.reqcols['star']['view'] = this.isStar;
    this.reqcols['check']['view'] = !this.isStar;

    if (this.isStar === false) {
      this.recentFiles.forEach((e) => ((e as any)['bIsStar'] = this.isStar));
    }
    this.cdr.detectChanges();
  }

  OnSelected($event: any) {
    this.OnFileSelected.emit($event);
  }

  ngOnChanges(_changes: SimpleChanges): void {
    this.cdr.detectChanges();
  }
  ngOnDestroy(): void {
    this.reqcols['check']['view'] = true;
    this.closeDialog();
    this.evsubscription?.unsubscribe();
    this.handleSelectionEvent();
  }

  private addSelectedFileId(id: string): void {
    if (!this.nSelectedFilesid.includes(id)) {
      this.nSelectedFilesid.push(id);
    }
  }

  private removeSelectedFileId(id: string): void {
    const index = this.nSelectedFilesid.indexOf(id);
    if (index > -1) {
      this.nSelectedFilesid.splice(index, 1);
    }
  }

  private onRowSelectionChange(file: presentGetFiles, checked: boolean): void {
    file.cIscheck = checked;

    if (checked) {
      this.addSelectedFileId(file.nBundledetailid);
      return;
    }

    if (!this.removedDocs.includes(file.nBundledetailid)) {
      this.removedDocs.push(file.nBundledetailid);
    }
    this.removeSelectedFileId(file.nBundledetailid);
  }

  tableEvent(event: { event: string; data: any }, file: presentGetFiles): void {
    if (event.event !== 'SELECTED') return;

    this.onRowSelectionChange(file, !!event.data?.cIscheck);
    this.cdr.detectChanges();
    this.handleSelectionEvent();
  }

  checkEventSub(): void {
    this.evsubscription = this.cs.functionCalled$.subscribe((data) => {
      if (data == 'SEARCH_FILES') {
        void this.getrecentfile(1);
      }
      else if (data == 'SEARCH_CLOSE') {
        if (this.cSearch != '' && (!this.cm.searchName || this.cm.searchText == '')) {
          void this.getrecentfile(1);
        }
      } else if (data == 'DOWNLOAD-FILE') {
        void this.generateReport();
      }
    });
  }


  sort_array(event) {
    const { key, flag } = event;
    this.cLastOtype = flag;
    this[flag] = this[flag] ? !this[flag] : true;
    this.cSortby = key;
    this.getrecentfile(1)
  }

  async generateReport() {
    try {
      const nSelectedFilesid = this.recentFiles.filter((a) => a.cIscheck).map((e) => e.nBundledetailid);
      const nDTaskid = this.dialogRef?.componentInstance?.nDTaskid ?? null;
      const mdl: downloadReport = {
        nCaseid: this.nCaseid,
        nTypeid: this.presentSession?.nTypeid || this.nTypeid,
        cPname: this.cPname,
        nSubtypeid: this.nSubtypeid || 0,
        nDTaskid: nDTaskid,
        jFiles: '{' + nSelectedFilesid.map(e => e).toString() + '}',
      };

      if (this.dStartDt && this.dEndDt) {
        mdl['dStartDt'] = this.dStartDt;
        mdl['dEndDt'] = this.dEndDt;
      }
      await this.PSservice.downloadFiles(mdl);
      this.closeDialog();
    } catch (error) {
      this.tost.error(ErrorHandlerUtil.getErrorMessage(error));
    }
  }

  checkDialogType() {
    return !!this.dialogRef?.componentInstance?.type;
  }

  private getPresentationActionLabel(): string {
    switch (this.presentDocType) {
      case 'F':
        return 'Go to presentation';
      case 'C':
        return 'Review Core Files';
      default:
        return 'Next: File Schedule';
    }
  }


  openactionbar() {
    const folder = 0;
    const files = this.nSelectedFilesid.length;
    let selectedIds = { jFiles: '{}' };
    if (files === 0) {
      this.closeDialog();
      return;
    }

    if (!this.checkDialogType()) {
      selectedIds = {
        jFiles: '{' + this.nSelectedFilesid.map(e => e).toString() + '}',
      }
    }

    if (this.dialogRef) {
      this.dialogRef.componentInstance.files = files;
      this.dialogRef.componentInstance.jFolders = '{}';
      this.dialogRef.componentInstance.jFiles = '{' + this.nSelectedFilesid.map(e => e).toString() + '}';
      this.cdr.detectChanges();
      return;
    }

      const buttons: ActionbarButtonConfig[] = [
        ACTIONBAR_BUTTONS.DOWNLOAD,
        {
          ...ACTIONBAR_BUTTONS.PRESENTATION,
          name: this.getPresentationActionLabel(),
        },
      ];
      this.dialogRef = this.dialog.open(ActionbarComponent, {
        width: 'fit-content',
        height: 'fit-content',
        hasBackdrop: false,
        position: { right: '0px', top: '0px' },
        panelClass: ['nobackground', 'noshadow', 'norounded', 'actionbarpanel'],
        data: {
          buttons: buttons,
          files: files,
          folders: 0, // this.folder,
          isadmin: false,
          nCaseid: this.nCaseid,
          nSectionid: 0,
          jFiles: selectedIds.jFiles,
          jFolders: `{}`,// this.selectedIds.jFolders
        }
      });
      this.dialogRef.afterClosed().subscribe(result => {
        if (result === ACTIONBAR_ACTION_TYPES.DOWNLOAD) {
          void this.generateReport();
        } else if (result === ACTIONBAR_ACTION_TYPES.PRESENTATION) {

          this.presentHistory.emit({ event: TOOL_EVENT_TYPES.PRESENT, data: { isshow: false } });
        } else if (result == 'Close') {
          this.closeDialog();
        }
        this.dialogRef = null;
      });
  }

  closeDialog() {
    if (this.dialogRef) {
      this.recentFiles.forEach((a) => (a.cIscheck = false));
      this.removedDocs = [];
      const files = this.recentFiles.filter((a) => a.cIscheck);
      this.handleSelection.emit({ files, removedDocs: this.removedDocs });
      this.dialogRef.close();
      this.dialogRef = null;
    }
  }

  checkSelectALl() {
    this.isCheckAll = this.recentFiles.filter(e => e.cIscheck).length == this.recentFiles.length;
  }

  async selectAllFiles(event) {
    if (event.checked) {
      this.recentFiles.forEach((e) => (e.cIscheck = true));
      try {
        if (this.isCheckAll) {
          if (!this.jFileids?.length)
            this.jFileids = await this.getALLRecentFiles();
          this.nSelectedFilesid = this.jFileids
        }
      } catch (error) {
        this.tost.error(ErrorHandlerUtil.getErrorMessage(error));
      }
    } else {
      this.removedDocs = this.nSelectedFilesid?.length ? this.nSelectedFilesid : this.recentFiles.filter(e => e.cIscheck).map(e => e.nBundledetailid);
      this.nSelectedFilesid = [];
      this.recentFiles.forEach((e) => (e.cIscheck = false));
    }
    this.handleSelectionEvent();
  }


  async getALLRecentFiles(): Promise<string[]> {
    try {
      const mdl: RecentFilesIDS = {
        nCaseid: this.nCaseid,
        nTypeid: this.presentSession?.nTypeid || this.nTypeid,
        cSearch: this.cm.searchText,
        searchName: this.cm.searchName,
        cPname: this.cPname
      };
      this.cSearch = this.cm.searchText;
      if (this.nSubtypeid > 0) {
        mdl['nSubtypeid'] = this.nSubtypeid;
      }
      if (this.dStartDt && this.dEndDt) {
        mdl['dStartDt'] = this.dStartDt;
        mdl['dEndDt'] = this.dEndDt;
      }
      const res = await this.PSservice.recentFilesIDS(mdl);
      return res?.jIDs || [];
    }
    catch (error) {
      this.tost.error(ErrorHandlerUtil.getErrorMessage(error));
      return [];
    }

  }

}
